import unittest
from candidate import max_element

class TestMaxElement(unittest.TestCase):
    def test_max_element_normal_case(self):
        self.assertEqual(max_element([1, 2, 3]), 3)

    def test_max_element_mixed_numbers(self):
        self.assertEqual(max_element([5, 3, -5, 2, -3, 3, 9, 0, 123, 1, -10]), 123)

    def test_max_element_single_element(self):
        self.assertEqual(max_element([42]), 42)

    def test_max_element_empty_list(self):
        with self.assertRaises(IndexError):
            max_element([])

    def test_max_element_none_input(self):
        with self.assertRaises(TypeError):
            max_element(None)

    def test_max_element_non_list_input(self):
        with self.assertRaises(TypeError):
            max_element("not a list")

    def test_max_element_all_negative_numbers(self):
        self.assertEqual(max_element([-1, -2, -3, -5]), -1)

    def test_max_element_all_identical_elements(self):
        self.assertEqual(max_element([7, 7, 7, 7]), 7)

    def test_max_element_with_floats(self):
        self.assertAlmostEqual(max_element([1.5, 2.5, 0.5]), 2.5)

    def test_max_element_with_mixed_floats_and_ints(self):
        self.assertEqual(max_element([1, 2.5, 3, 4.7]), 4.7)

    def test_max_element_with_nested_lists(self):
        with self.assertRaises(TypeError):
            max_element([1, [2, 3]])

    def test_max_element_with_unhashable_elements(self):
        with self.assertRaises(TypeError):
            max_element([1, [2], 3])

    def test_max_element_with_large_numbers(self):
        self.assertEqual(max_element([10**18, 10**18 - 1]), 10**18)

    def test_max_element_with_large_negative_numbers(self):
        self.assertEqual(max_element([-10**18, -10**18 + 1]), -10**18)
